import java.util.Scanner;

public class Employee {
    private int empNo;
    private String name;
    private double basic;
    private double da;
    private double hra;
    private double pf;
    private double netSalary;

    public void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Employee Number: ");
        empNo = sc.nextInt();
        sc.nextLine(); // consume newline
        System.out.print("Enter Employee Name: ");
        name = sc.nextLine();
        System.out.print("Enter Basic Salary: Rs. ");
        basic = sc.nextDouble();
    }

    public void compute() {
        da = 0.30 * basic;
        hra = 0.15 * basic;
        pf = 0.12 * basic;
        double gross = basic + da + hra;
        netSalary = gross - pf;
    }

    public void display() {
        System.out.println("\n========================================");
        System.out.println("            SALARY STATEMENT            ");
        System.out.println("========================================");
        System.out.println("Emp Number : " + empNo);
        System.out.println("Emp Name   : " + name);
        System.out.printf("Basic Pay  : Rs. %.2f\n", basic);
        System.out.printf("DA (30%%)   : Rs. %.2f\n", da);
        System.out.printf("HRA (15%%)  : Rs. %.2f\n", hra);
        System.out.printf("PF (12%%)   : Rs. %.2f\n", pf);
        System.out.println("----------------------------------------");
        System.out.printf("Net Salary : Rs. %.2f\n", netSalary);
        System.out.println("========================================");
    }

    public static void main(String[] args) {
        Employee emp = new Employee();
        emp.accept();
        emp.compute();
        emp.display();
    }
}
```

