import java.util.Scanner;

public class LinearSearchNames {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] names = new String[10];

        System.out.println("Enter 10 names:");
        for (int i = 0; i < 10; i++) {
            names[i] = sc.nextLine().trim();
        }

        System.out.print("\nEnter the name to search for: ");
        String searchName = sc.nextLine().trim();

        int foundIndex = -1;
        for (int i = 0; i < names.length; i++) {
            if (names[i].equalsIgnoreCase(searchName)) {
                foundIndex = i;
                break;
            }
        }

        if (foundIndex != -1) {
            System.out.println("Name found at index: " + foundIndex + " (Position: " + (foundIndex + 1) + ")");
        } else {
            System.out.println("Name does not exist in the list.");
        }

        sc.close();
    }
}
