import java.util.Scanner;

public class StringCaseToggle {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a string:");
        String input = sc.nextLine();

        int upperCount = 0;
        int lowerCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        StringBuilder toggled = new StringBuilder();

        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);

            if (Character.isUpperCase(ch)) {
                upperCount++;
                toggled.append(Character.toLowerCase(ch));
            } else if (Character.isLowerCase(ch)) {
                lowerCount++;
                toggled.append(Character.toUpperCase(ch));
            } else if (Character.isDigit(ch)) {
                digitCount++;
                toggled.append(ch);
            } else {
                specialCount++;
                toggled.append(ch);
            }
        }

        System.out.println("\n--- Character Count Summary ---");
        System.out.println("Uppercase Letters : " + upperCount);
        System.out.println("Lowercase Letters : " + lowerCount);
        System.out.println("Numeric Digits    : " + digitCount);
        System.out.println("Special Characters: " + specialCount);
        System.out.println("\nToggled Case String: " + toggled.toString());

        sc.close();
    }
}
```

