import java.util.Scanner;

public class ArmstrongNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a 3-digit integer: ");
        int num = sc.nextInt();

        // Validation for 3-digit number
        if (num < 100 || num > 999) {
            System.out.println("Invalid input. Please enter a valid 3-digit positive number (100 to 999).");
            return;
        }

        int temp = num;
        int sumCubes = 0;

        while (temp > 0) {
            int d = temp % 10;
            sumCubes += (d * d * d);
            temp /= 10;
        }

        System.out.println("Sum of cubes of digits = " + sumCubes);
        if (sumCubes == num) {
            System.out.println(num + " is an ARMSTRONG NUMBER.");
        } else {
            System.out.println(num + " is NOT an Armstrong Number.");
        }

        sc.close();
    }
}
```

