import java.util.Scanner;

public class MatrixRowColSum {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] mat = new int[3][3];

        System.out.println("Enter 9 elements for a 3x3 matrix:");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                mat[i][j] = sc.nextInt();
            }
        }

        // Display Matrix
        System.out.println("\n--- Matrix ---");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                System.out.print(mat[i][j] + "\t");
            }
            System.out.println();
        }

        // Row Sums
        System.out.println("\n--- Row Sums ---");
        for (int i = 0; i < 3; i++) {
            int rowSum = 0;
            for (int j = 0; j < 3; j++) {
                rowSum += mat[i][j];
            }
            System.out.println("Sum of Row " + (i + 1) + " = " + rowSum);
        }

        // Column Sums
        System.out.println("\n--- Column Sums ---");
        for (int j = 0; j < 3; j++) {
            int colSum = 0;
            for (int i = 0; i < 3; i++) {
                colSum += mat[i][j];
            }
            System.out.println("Sum of Column " + (j + 1) + " = " + colSum);
        }

        sc.close();
    }
}
```

