public class AreaOverload {
    // Method 1: Area of Circle
    public double area(double radius) {
        return Math.PI * radius * radius;
    }

    // Method 2: Area of Rectangle
    public double area(double length, double breadth) {
        return length * breadth;
    }

    // Method 3: Area of Triangle (Heron's formula)
    public double area(double a, double b, double c) {
        double s = (a + b + c) / 2.0;
        return Math.sqrt(s * (s - a) * (s - b) * (s - c));
    }

    public static void main(String[] args) {
        AreaOverload calc = new AreaOverload();

        System.out.printf("Area of Circle (r=7.0): %.2f sq. units\n", calc.area(7.0));
        System.out.printf("Area of Rectangle (l=12.0, b=5.0): %.2f sq. units\n", calc.area(12.0, 5.0));
        System.out.printf("Area of Triangle (a=3, b=4, c=5): %.2f sq. units\n", calc.area(3.0, 4.0, 5.0));
    }
}
